import{_ as r,C as d,o as s,c as n,aj as e,E as o}from"./framework.js";const p=JSON.parse('{"title":"基础 · 基础 Tab | Cms / Settings / Basic | Documentation","description":"基础 · 基础 Tab in Kooboo: 本 Tab 配置站点 对外标识、预览 Base URL、HTTPS/SPA 行为、多语言 culture，以及 导入 / 导出 整站包。","frontmatter":{"title":"基础 · 基础 Tab | Cms / Settings / Basic | Documentation","description":"基础 · 基础 Tab in Kooboo: 本 Tab 配置站点 对外标识、预览 Base URL、HTTPS/SPA 行为、多语言 culture，以及 导入 / 导出 整站包。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/basic/general.html"}]]},"headers":[],"relativePath":"zh/cms/settings/basic/general.md","filePath":"cms/settings/basic/general.md","lastUpdated":1780890267000}'),l={name:"zh/cms/settings/basic/general.md"};function i(c,t,h,g,b,u){const a=d("DocImage");return s(),n("div",null,[t[0]||(t[0]=e('<h1 id="基础-·-基础-tab" tabindex="-1">基础 · 基础 Tab <a class="header-anchor" href="#基础-·-基础-tab" aria-label="Permalink to &quot;基础 · 基础 Tab&quot;">​</a></h1><blockquote><p>Tab：<strong>基础</strong> · <code>name=basic</code><br> 深链：<code>/_Admin/system/settings?SiteId={站点GUID}&amp;name=basic</code></p></blockquote><p>本 Tab 配置站点 <strong>对外标识</strong>、<strong>预览 Base URL</strong>、HTTPS/SPA 行为、<strong>多语言</strong> culture，以及 <strong>导入 / 导出</strong> 整站包。</p>',3)),o(a,{src:"/cms/settings/settings-basic-general.png",alt:"基础 Tab",width:"1120"}),t[1]||(t[1]=e('<h2 id="站点信息" tabindex="-1">站点信息 <a class="header-anchor" href="#站点信息" aria-label="Permalink to &quot;站点信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>显示名称</strong></td><td>后台与控制面板展示的站点名（<code>displayName</code>）</td></tr><tr><td><strong>Base URL</strong></td><td>站点预览与生成绝对链接的基准地址（<code>previewUrl</code>），须与 <a href="./../domains.html">域名管理</a> 中主访问域一致或互为别名</td></tr><tr><td><strong>强制 SSL</strong></td><td>开启后 HTTP 请求重定向 HTTPS。若前置 CDN/代理已处理 HTTPS 且出现 <strong>过多重定向</strong>，应关闭此项</td></tr><tr><td><strong>SPA</strong></td><td>开启后将 <strong>404 重定向到主页</strong>，适合单页应用路由由前端接管</td></tr></tbody></table><h2 id="多语言" tabindex="-1">多语言 <a class="header-anchor" href="#多语言" aria-label="Permalink to &quot;多语言&quot;">​</a></h2><p>通过 <strong>多语言</strong> 分组面板开关 <code>enableMultilingual</code>。关闭后保存时会收起为仅保留 <strong>默认语言</strong> 一条 culture，并关闭路径模式相关项。</p>',4)),o(a,{src:"/cms/settings/settings-basic-multilingual.png",alt:"多语言配置",width:"1120"}),t[2]||(t[2]=e('<h3 id="语言列表" tabindex="-1">语言列表 <a class="header-anchor" href="#语言列表" aria-label="Permalink to &quot;语言列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>添加</strong></td><td>从内置 culture 列表选择，或 <strong>输入自定义</strong> 两位小写字母代码（如 <code>en</code>、<code>zh</code>）；非法格式会提示</td></tr><tr><td><strong>显示名</strong></td><td>每种语言的展示名称（如「简体中文」）</td></tr><tr><td><strong>删除</strong></td><td>至少保留一种语言时可删</td></tr></tbody></table><h3 id="默认语言" tabindex="-1">默认语言 <a class="header-anchor" href="#默认语言" aria-label="Permalink to &quot;默认语言&quot;">​</a></h3><p><strong>默认语言</strong> 下拉仅列出当前 culture 列表中的项；删除默认语系时会自动改选列表第一项。</p><h3 id="路径模式" tabindex="-1">路径模式 <a class="header-anchor" href="#路径模式" aria-label="Permalink to &quot;路径模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><strong>参数模式</strong></td><td>语言通过查询参数等方式传递（<code>enableSitePath=false</code>）</td></tr><tr><td><strong>路由模式</strong></td><td>URL 路径前缀区分语言（<code>enableSitePath=true</code>）</td></tr></tbody></table><p>路由模式下可配置 <strong>默认语言前缀</strong>：是否在默认语言 URL 上也带语言前缀。</p><h3 id="其它开关" tabindex="-1">其它开关 <a class="header-anchor" href="#其它开关" aria-label="Permalink to &quot;其它开关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开关</th><th>说明</th></tr></thead><tbody><tr><td><strong>自动检测语言</strong></td><td>按访客 <code>Accept-Language</code> 等自动选择 culture</td></tr><tr><td><strong>HrefLang</strong></td><td>输出 <code>hreflang</code> 链接利于搜索引擎多语言</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">与 SPA 多语言的区别</p><p>本页配置的是 <strong>Kooboo 站点 culture</strong>（页面/内容多语言、URL 规则）。<a href="./../../development/spa-multilingual.html">开发 → SPA 多语言</a> 管理的是 <strong>前端 SPA 语言 JSON</strong>，二者数据源不同，勿混用。</p></div><p>脚本与模板侧常用 <a href="/kb-docs/zh/api/label/">k.label</a> 按 culture 取文案。</p><h2 id="导入-导出站点包" tabindex="-1">导入 / 导出站点包 <a class="header-anchor" href="#导入-导出站点包" aria-label="Permalink to &quot;导入 / 导出站点包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><strong>导入包</strong></td><td><code>site·edit</code></td><td>上传 Kooboo 站点包（扩展名以产品 <code>importAccept</code> 为准），覆盖合并当前站点内容</td></tr><tr><td><strong>导出站点</strong></td><td><code>site·export</code></td><td>打开导出对话框，选择范围后下载站点包</td></tr></tbody></table><p>导入成功后页面会 <strong>重新加载站点</strong> 配置。导出与 <a href="./../../operations/sync.html">协作同步</a> 的推送/拉取是不同机制：本处为单文件包导入导出。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./">基础设置概述</a></li><li><a href="./access.html">访问控制</a></li><li><a href="./../domains.html">域名管理</a></li></ul>',16))])}const _=r(l,[["render",i]]);export{p as __pageData,_ as default};
